=<!doctype html>
<html>
<head>
  <meta charset="utf-8" />
  <meta name="viewport" content="width=device-width,initial-scale=1" />
  <title>New Form Submission</title>
  <style>
    :root{
      --bg:#f4f7fb;
      --card:#ffffff;
      --accent:#0A66C2;        /* primary accent (LinkedIn-blue-like) */
      --muted:#6b7280;
      --success:#10b981;
      --shadow: 0 6px 18px rgba(11,35,71,0.08);
      --radius:12px;
      --mono: "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
    }
    body{
      margin:0;
      background: linear-gradient(180deg, var(--bg), #eef4ff);
      font-family: var(--mono);
      color:#0b1220;
      -webkit-font-smoothing:antialiased;
    }
    .container{
      width:100%;
      padding:28px 16px;
      box-sizing:border-box;
    }
    .card{
      max-width:720px;
      margin:0 auto;
      background:var(--card);
      border-radius:var(--radius);
      box-shadow:var(--shadow);
      overflow:hidden;
    }
    .header{
      padding:22px 24px;
      display:flex;
      align-items:center;
      gap:16px;
      background: linear-gradient(90deg, rgba(10,102,194,0.06), rgba(16,185,129,0.03));
    }
    .logo {
      width:48px;
      height:48px;
      border-radius:10px;
      display:inline-flex;
      align-items:center;
      justify-content:center;
      font-weight:700;
      color:white;
      background:var(--accent);
      box-shadow: 0 2px 8px rgba(10,102,194,0.16);
    }
    .title{
      font-size:16px;
      font-weight:700;
      color:#05203a;
    }
    .meta{
      padding:18px 24px;
      border-bottom:1px solid #f1f5f9;
      display:flex;
      gap:18px;
      flex-wrap:wrap;
    }
    .meta .item{
      font-size:13px;
      color:var(--muted);
    }
    .content{
      padding:20px 24px 28px 24px;
    }
    .fields-table{
      width:100%;
      border-collapse:collapse;
      margin-top:8px;
    }
    .fields-table th{
      text-align:left;
      font-size:13px;
      color:var(--muted);
      padding:8px 10px;
      background: #fbfdff;
    }
    .fields-table td{
      padding:10px;
      font-size:14px;
      border-top:1px solid #f3f5f8;
      vertical-align:top;
    }
    .cta{
      margin-top:18px;
      display:flex;
      gap:12px;
      flex-wrap:wrap;
    }
    .btn{
      display:inline-block;
      padding:10px 14px;
      border-radius:10px;
      text-decoration:none;
      font-weight:600;
      font-size:14px;
      box-shadow:0 6px 18px rgba(10,102,194,0.08);
    }
    .btn-primary{ background:var(--accent); color:#fff; }
    .btn-ghost{ background:transparent; color:var(--accent); border:1px solid rgba(10,102,194,0.12); }
    .footer{
      padding:16px 24px;
      font-size:12px;
      color:var(--muted);
      border-top:1px solid #f1f5f9;
      display:flex;
      justify-content:space-between;
      align-items:center;
    }
    .small{
      font-size:12px;
      color:#8b93a3;
    }
    @media (max-width:520px){
      .card{ margin:0 12px; }
      .meta{ gap:10px; padding:12px; }
      .header{ padding:16px; }
    }
  </style>
</head>
<body>
  <div class="container">
    <div class="card" role="article" aria-label="New form submission notification">
      <div class="header">
        <div class="logo">MK</div>
        <div>
          <div class="title">New submission received — {{ $json.Name }}</div>
        </div>
      </div>

      <div class="meta" aria-hidden="false">
        <div class="item">Submitted at: <strong>{{ $json.Time }}</strong></div>
        <div class="item">Source: <strong>client intake form</strong></div>
      </div>

      <div class="content">
        <p style="margin:0; color:#12304a; font-weight:600;">Primary contact</p>
        <table class="fields-table" role="table" aria-label="Primary contact">
          <tr>
            <th style="width:160px">Field</th>
            <th>Value</th>
          </tr>
          <tr>
            <td><strong>Name</strong></td>
            <td>{{ $('On form submission').item.json['Name '] }}</td>
          </tr>
          <tr>
            <td><strong>Email</strong></td>
            <td>{{ $('On form submission').item.json.Email }}</td>
          </tr>
        </table>
        </table>

      </div>

      <div class="footer">
        <div>Team • ProfileMagnet</div>
        <div class="small">If this looks suspicious, investigate or mark as spam.</div>
      </div>
    </div>
  </div>
</body>
</html>

=<!doctype html>
<html>
<head>
  <meta charset="utf-8" />
  <meta name="viewport" content="width=device-width,initial-scale=1" />
  <title>Thanks — we received your submission</title>
  <style>
    :root{
      --bg:#f9fbff;
      --card:#ffffff;
      --accent:#0A66C2;
      --accent-2:#06b6d4;
      --muted:#5b6470;
      --radius:14px;
      --shadow:0 10px 30px rgba(9,30,66,0.08);
      --mono: "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
    }
    body{ margin:0; background:linear-gradient(180deg,#fbfdff,#f2f8ff); font-family:var(--mono); color:#0b1220; }
    .wrap{ padding:28px 16px; }
    .email{ max-width:680px; margin:0 auto; background:var(--card); border-radius:var(--radius); box-shadow:var(--shadow); overflow:hidden; }
    .hero{ padding:28px 24px; text-align:center; background:
      linear-gradient(180deg, rgba(10,102,194,0.06), rgba(6,182,212,0.03)); }
    .badge{ display:inline-block; background:var(--accent); color:#fff; padding:10px 14px; border-radius:10px; font-weight:700; }
    h1{ margin:14px 0 6px 0; font-size:20px; color:#05203a; }
    p.lead{ margin:0; color:var(--muted); font-size:15px; }
    .body{ padding:20px 24px 28px 24px; }
    .summary{
      margin-top:12px;
      background:#fbfdff;
      border-radius:10px;
      padding:12px;
      border:1px solid #eef6ff;
    }
    .summary .row{ display:flex; gap:12px; align-items:center; margin-bottom:8px; }
    .label{ min-width:110px; font-weight:700; color:#0b1220; font-size:14px; }
    .value{ color:#16324a; font-size:14px; }
    .actions{ margin-top:18px; display:flex; gap:12px; flex-wrap:wrap; }
    .btn{ text-decoration:none; padding:10px 14px; border-radius:10px; font-weight:700; font-size:14px; display:inline-block; }
    .btn-primary{ background:var(--accent); color:#fff; }
    .btn-secondary{ background:transparent; color:var(--accent); border:1px solid rgba(10,102,194,0.12); }
    .note{ margin-top:14px; font-size:13px; color:var(--muted); }
    .footer{ padding:18px 24px; border-top:1px solid #eef5ff; font-size:13px; color:var(--muted); display:flex; justify-content:space-between; align-items:center; }
    @media (max-width:520px){
      .label{ min-width:88px; }
      .hero{ padding:20px; }
    }
  </style>
</head>
<body>
  <div class="wrap">
    <div class="email" role="article" aria-label="Thank you for your submission">
      <div class="hero">
        <div class="badge">Thanks!</div>
        <h1>Hello {{ $json.Name }},</h1>
        <p class="lead">We received your submission for <strong>Client intake form</strong>. Thanks for reaching out — we've got it and will review it shortly.</p>
      </div>

      <div class="body">
        <div class="summary" role="group" aria-label="Submission summary">
          <div class="row">
            <div class="label">Name</div>
            <div class="value">{{ $('On form submission').item.json['Name '] }}</div>
          </div>
          <div class="row">
            <div class="label">Email</div>
            <div class="value">{{ $('On form submission').item.json.Email }}</div>
          </div>
        </div>

        <p class="note">
          Typical response time: <strong>1–2 business days</strong>.
        </p>
      </div>

      <div class="footer">
        <div>ProfileMagnet</div>
        <div style="font-size:12px;color:#97a0b5;">Ref: • {{ $('On form submission').item.json.submittedAt }}</div>
      </div>
    </div>
  </div>
</body>
</html>
